def quran(surah, ayah):
    path = ROOT / f'assets/data/quran/trans/ur/surah_{surah}.json'
    return json.loads(path.read_text(encoding='utf-8'))['ayahs'][ayah - 1]


def excerpt(surah, ayah, start):
    text = quran(surah, ayah)
    return text[text.index(start):]


def rendering(dua):
    dua_id = dua['id']
    prefix, suffix = dua_id.split('_', 1)
    if suffix == 'ayat_kursi':
        return 'آیت الکرسی', quran(2, 255)
    if suffix in ('ikhlas', 'falaq', 'nas'):
        number = {'ikhlas': 112, 'falaq': 113, 'nas': 114}[suffix]
        name = {'ikhlas': 'سورۃ الاخلاص', 'falaq': 'سورۃ الفلق', 'nas': 'سورۃ الناس'}[suffix]
        count = {112: 4, 113: 5, 114: 6}[number]
        # The Arabic cards include basmalah; preserve its exact translator text.
        return name, quran(1, 1) + '\n\n' + '\n'.join(quran(number, n) for n in range(1, count + 1))
    if suffix == 'hasbiyallah':
        return 'اللہ میرے لیے کافی ہے', excerpt(9, 129, 'میرے لیے اللہ کافی ہے')
    if suffix == 'ushhiduka':
        time = 'صبح' if prefix == 'morning' else 'شام'
        return 'اللہ کو گواہ بنانا', f'اے اللہ! میں نے {time} کی، تجھے، تیرے عرش کے اٹھانے والوں، تیرے فرشتوں اور تیری تمام مخلوق کو گواہ بناتے ہوئے کہ تو ہی اللہ ہے، تیرے سوا کوئی معبود نہیں، تو اکیلا ہے، تیرا کوئی شریک نہیں، اور محمد ﷺ تیرے بندے اور رسول ہیں۔'
    if suffix == 'fitrah':
        time = 'صبح' if prefix == 'morning' else 'شام'
        return 'اسلام کی فطرت پر', f'ہم نے اسلام کی فطرت، اخلاص کے کلمے، اپنے نبی محمد ﷺ کے دین اور اپنے والد ابراہیم کی ملت پر {time} کی، جو یکسو مسلمان تھے اور مشرکوں میں سے نہ تھے۔'
    if suffix in ('ma_asbaha_nimah', 'ma_amsa_nimah'):
        time = 'صبح' if prefix == 'morning' else 'شام'
        return 'اللہ کی نعمت کا اقرار', f'اے اللہ! اس {time} مجھے یا تیری کسی مخلوق کو جو نعمت ملی، وہ صرف تیری طرف سے ہے، تیرا کوئی شریک نہیں۔ پس تمام تعریف اور تمام شکر تیرے لیے ہے۔'
    if dua_id == 'waking_imran_190_200':
        return 'سورۃ آل عمران کی آخری گیارہ آیات', '\n\n'.join(f'({urdu_digits(n)}) {quran(3, n)}' for n in range(190, 201))
    fragments = {
        'forgiveness_yunus': ('حضرت یونس کی دعا', 21, 87, 'الٰہی تیرے سوا'),
        'forgiveness_rabbana_zalamna': ('حضرت آدم کی دعا', 7, 23, 'اے ہمارے رب!'),
        'forgiveness_rabbana_la_tuakhidhna': ('بھول اور خطا پر معافی کی دعا', 2, 286, 'اے ہمارے رب!'),
        'forgiveness_rabbanaghfirlana': ('اے ہمارے رب! ہم ایمان لائے', 3, 16, 'اے ہمارے رب!'),
        'distress_hasbunallah': ('اللہ ہمارے لیے کافی ہے', 3, 173, 'ہمیں اللہ کافی ہے'),
    }
    if dua_id in fragments:
        title, surah, ayah, start = fragments[dua_id]
        return title, excerpt(surah, ayah, start)
    if dua_id == 'distress_musibah':
        return 'مصیبت یا نقصان کے وقت', excerpt(2, 156, 'ہم تو خود اللہ تعالیٰ') + '۔ اے اللہ! میری مصیبت پر مجھے اجر دے اور اس کے بدلے مجھے اس سے بہتر عطا فرما۔'
    if dua_id == 'travel_setting_off':
        return 'سفر پر روانہ ہوتے وقت', 'اللہ سب سے بڑا ہے، تین مرتبہ۔ ' + excerpt(43, 13, 'پاک ذات ہے') + '۔ ' + quran(43, 14) + '۔ اے اللہ! ہم اپنے اس سفر میں تجھ سے نیکی، تقویٰ اور ایسے عمل کا سوال کرتے ہیں جن سے تو راضی ہو۔ اے اللہ! ہمارا یہ سفر آسان فرما اور اس کی دوری کم فرما۔ اے اللہ! تو سفر میں ہمارا ساتھی اور گھر والوں کا نگہبان ہے۔ اے اللہ! میں سفر کی سختی، رنج دینے والے منظر اور مال و گھر والوں میں بری واپسی سے تیری پناہ مانگتا ہوں۔'
    return FORMULAS[suffix]


def urdu_digits(value):
    return str(value).translate(str.maketrans('0123456789٠١٢٣٤٥٦٧٨٩', '۰۱۲۳۴۵۶۷۸۹۰۱۲۳۴۵۶۷۸۹'))


def reference(arabic):
    replacements = {
        'القرآن الكريم': 'قرآن کریم', 'صحيح البخاري': 'صحیح بخاری',
        'صحيح مسلم': 'صحیح مسلم', 'سنن أبي داود': 'سنن ابو داؤد',
        'سنن الترمذي': 'سنن ترمذی', 'جامع الترمذي': 'جامع ترمذی',
        'الترمذي': 'ترمذی', 'النسائي': 'نسائی', 'ابن ماجه': 'ابن ماجہ',
        'الطبراني': 'طبرانی', 'المعجم الأوسط': 'المعجم الاوسط',
        'عمل اليوم والليلة': 'عمل الیوم واللیلہ', 'صححه الألباني': 'البانی نے صحیح قرار دیا',
        'تُقرأ دبر كل صلاة': 'ہر نماز کے بعد پڑھی جاتی ہے', 'مسند أحمد': 'مسند احمد',
        'البقرة': 'البقرہ', 'الأعراف': 'الاعراف', 'الأنبياء': 'الانبیاء',
        'آل عمران': 'آل عمران', 'النور': 'النور',
    }
    for old, new in replacements.items():
        arabic = arabic.replace(old, new)
    return urdu_digits(arabic)


def generate():
    duas = json.loads((ROOT / 'assets/data/duas.json').read_text(encoding='utf-8'))
    ar = json.loads((ROOT / 'assets/data/duas.ar.json').read_text(encoding='utf-8'))
    out = {'_meta': {
        'status': 'DRAFT — original project Urdu hadith renderings require qualified Urdu and scholarly review before release',
        'scope': 'Urdu titles, meanings, references, virtues and practical instructions; base Arabic recitations remain unchanged.',
        'authorship': 'Hadith prose is an original project rendering of the existing bundled Arabic/English content and its references, not a published translator transcription.',
        'quran': {'translator': 'Muhammad Junagarhi', 'edition': 'ur.junagarhi',
                  'source': 'https://tanzil.net/trans/ur.junagarhi',
                  'terms': 'https://tanzil.net/trans/',
                  'method': 'Verbatim complete verses, complete surahs or exact suffix excerpts from bundled ur/surah_N.json. Mixed hadith/Quran texts retain exact Quran excerpts.'},
        'referencePolicy': 'Reference numbers and reported grading notes follow current bundled content; this overlay does not independently authenticate narrations.',
        'osoulEdition': 'Official Urdu Hisn edition inspected for source feasibility only; no wording copied or attribution to its translator claimed.'
    }}
    for dua in duas:
        dua_id = dua['id']
        title, translation = rendering(dua)
        entry = {'title': title, 'translation': translation,
                 'reference': reference(ar[dua_id]['reference'])}
        if dua.get('virtue'):
            entry['virtue'] = VIRTUES[dua_id]
        if dua.get('instruction'):
            entry['instruction'] = INSTRUCTIONS[dua_id]
        for field, text in entry.items():
            if not text.strip() or re.search('[A-Za-z]', text):
                raise ValueError(f'{dua_id}.{field} is blank or retains Latin prose')
        out[dua_id] = entry
    return out


if __name__ == '__main__':
    output = ROOT / 'assets/data/duas.ur.json'
    result = generate()
    output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(f'Wrote {output}: {len(result)-1} Urdu entries, no English field fallbacks')
